# Model 1 of the 3D matching coupled Poisson example (tetrahedra):
# [0.0,0.5] x [0,1] x [0,1], 2 x 2 x 2 cubes, generated by cubemesh.
# Executed by pdeapp.py, which defines pde, mesh, exasim and numpy.
pde[0], mesh[0] = exasim.initializeexasim()

pde[0]['model'] = "ModelD"
pde[0]['modelfile'] = "pdemodel1"
pde[0]['modelnumber'] = 1
pde[0]['Cxxpreprocessing'] = 1
pde[0]['mpiprocs'] = 1
pde[0]['hybrid'] = 1
pde[0]['porder'] = 2
pde[0]['pgauss'] = 4
pde[0]['physicsparam'] = numpy.array([1.0])
pde[0]['tau'] = numpy.array([1.0])
pde[0]['NLiter'] = 4
pde[0]['NLtol'] = 1e-12
pde[0]['linearsolvertol'] = 1e-12
pde[0]['matvectol'] = 1e-12
pde[0]['GMRESrestart'] = 250
pde[0]['linearsolveriter'] = 600
pde[0]['interfacetype'] = 0

mesh[0]['p'], mesh[0]['t'] = exasim.Mesh.cubemesh(2, 2, 2, 0)[0:2]
mesh[0]['p'][0, :] = 0.5 * mesh[0]['p'][0, :]   # map x to [0,0.5]
# Boundaries: y = 0, x = 0.5, y = 1, x = 0, z = 0, z = 1
mesh[0]['boundaryexpr'] = [lambda p: abs(p[1, :]) < 1e-8, lambda p: abs(p[0, :] - 0.5) < 1e-8,
                          lambda p: abs(p[1, :] - 1) < 1e-8, lambda p: abs(p[0, :]) < 1e-8,
                          lambda p: abs(p[2, :]) < 1e-8, lambda p: abs(p[2, :] - 1) < 1e-8]
mesh[0]['boundarycondition'] = numpy.array([1, 2, 1, 1, 1, 1])
mesh[0]['interfacecondition'] = numpy.array([0, 1, 0, 0, 0, 0])   # boundary 2 is the coupled interface
pde[0]['interfacefluxmap'] = numpy.array([1])
